function enrichChapter(chapter, index) {
  const guidance = { ...JAVA_PATTERN_GUIDANCE, ...MICROSERVICE_PATTERN_GUIDANCE, ...ADDITIONAL_BLOG_GUIDANCE }[chapter.blogId]?.[chapter.title] || [];
  const editorial = TECH_BLOG_GUIDANCE[chapter.blogId];
  const whenToUse = editorial?.whenToUse || chapter.whenToUse || guidance[0] || "Use this chapter when its stated assumptions match the decision you need to make.";
  const practiceProblems = chapter.practiceProblems || "Practice set: one recognition problem, one implementation problem, and one variation that breaks the naive assumption.";
  const walkthrough = chapter.walkthrough || "Work through this chapter in three passes: first explain the idea in plain language, then trace the example with a small input, and finally test the boundary case that could invalidate the assumption.";
  return {
    ...chapter,
    diagramKey: chapterDiagramKey(chapter.blogId, chapter.title),
    lesson: `${chapter.lesson} When to use: ${whenToUse}`,
    diagram: chapter.diagram || `input → ${chapter.title.replace(/^\d+\.\s*/, "")} → verified output`,
    walkthrough,
    example: chapter.example,
    practiceProblems,
    exercise: `${chapter.exercise} Practice set: ${practiceProblems}`,
    quiz: chapter.quiz || `What invariant or contract must remain true after completing ${chapter.title.replace(/^\d+\.\s*/, "").toLowerCase()}?`,
    whenToUse,
    avoid: chapter.avoid || guidance[1] || editorial?.avoid || "",
    answer: chapter.answer || guidance[2] || editorial?.answers[chapter.title] || "",
    order: index + 1,
  };
}

export function listTechBlogs() {
  const fieldNotes = BACKEND_FIELD_NOTES.map(blog => ({
    ...blog,
    sections: [{ heading: '2-minute overview', body: blog.overview }, { heading: 'Verification scope', body: blog.scope }],
    lessons: blog.chapters.map(chapter => chapter.title),
    example: blog.trace.map(([time, event, meaning]) => `${time}: ${event}\n  ${meaning}`).join('\n'),
    practice: blog.interviewQuestions[0],
    chapters: blog.chapters.map(chapter => ({ ...chapter, whenToUse: 'Use the evidence to separate competing explanations.', walkthrough: chapter.exercise, diagram: chapter.example, quiz: blog.misconception.question })),
  }));
  return [...fieldNotes, ...TECH_BLOGS.map((blog) => ({ ...blog, patterns: blog.id === "design-patterns-in-18-minutes" ? INDUSTRY_DESIGN_PATTERNS : [], chapters: (COURSE_CHAPTERS[blog.id] || []).map((chapter, index) => enrichChapter({ ...chapter, blogId: blog.id }, index)) }))];
}
